using System;using System.Collections.Generic;using System.ComponentModel;using System.IO;using System.Runtime.InteropServices;using System.Text;using Microsoft.Win32.SafeHandles;
// Hold every ancestor against rename and the exact file against replacement throughout a read-only scan.
internal sealed class NativeScanLease:IDisposable {
 [StructLayout(LayoutKind.Sequential)]struct AttributeTag {internal uint Attributes,Tag;}
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern SafeFileHandle CreateFile(string path,uint access,uint share,IntPtr security,uint creation,uint flags,IntPtr template);
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetFileInformationByHandleEx(SafeFileHandle handle,int kind,out AttributeTag data,uint size);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern uint GetFinalPathNameByHandle(SafeFileHandle handle,StringBuilder path,uint size,uint flags);
 readonly List<SafeFileHandle> handles=new List<SafeFileHandle>();
 internal static string PhysicalDirectory(string path){using(var handle=CreateFile(Path.GetFullPath(path),0x80u,7u,IntPtr.Zero,3,0x02200000u,IntPtr.Zero)){if(handle.IsInvalid)throw new IOException("Storage directory unavailable.");AttributeTag tag;if(!GetFileInformationByHandleEx(handle,9,out tag,8)||(tag.Attributes&0x400)!=0)throw new IOException("Linked storage refused.");var final=new StringBuilder(32768);uint count=GetFinalPathNameByHandle(handle,final,32768,0);if(count==0||count>=32768)throw new IOException("Storage identity unavailable.");string actual=final.ToString();if(actual.StartsWith("\\\\?\\",StringComparison.Ordinal))actual=actual.Substring(4);if(!Path.IsPathRooted(actual)||actual.StartsWith("\\\\",StringComparison.Ordinal))throw new IOException("Remote storage refused.");return actual;}}
 internal static NativeScanLease Open(string path){var lease=new NativeScanLease();try{string full=Path.GetFullPath(path);var parents=new Stack<string>();string current=Path.GetDirectoryName(full);while(!string.IsNullOrEmpty(current)){parents.Push(current);current=Path.GetDirectoryName(current);}while(parents.Count>0)lease.Pin(parents.Pop(),true);lease.Pin(full,false);return lease;}catch{lease.Dispose();throw;}}
 void Pin(string path,bool directory){var handle=CreateFile(path,directory?0x80u:0x80000000u,1u,IntPtr.Zero,3,0x00200000u|(directory?0x02000000u:0),IntPtr.Zero);if(handle.IsInvalid){handle.Dispose();throw new IOException("File changed or cannot be retained.");}handles.Add(handle);AttributeTag tag;if(!GetFileInformationByHandleEx(handle,9,out tag,8)||(tag.Attributes&0x400)!=0)throw new IOException("Linked files are excluded.");var final=new StringBuilder(32768);uint count=GetFinalPathNameByHandle(handle,final,32768,0);if(count==0||count>=32768)throw new IOException("File identity unavailable.");string actual=final.ToString();if(actual.StartsWith("\\\\?\\",StringComparison.Ordinal))actual=actual.Substring(4);if(!string.Equals(actual.TrimEnd('\\'),Path.GetFullPath(path).TrimEnd('\\'),StringComparison.OrdinalIgnoreCase))throw new IOException("File location changed.");}
